#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>
#include <numeric>
int main(){
 int n,threshold;
 if(!(std::cin>>n>>threshold)||n<0||n>64||threshold< -10000||threshold>10000){std::cout<<"invalid\n";return 0;}
 std::vector<int>input;
 for(int i=0;i<n;++i){int x;if(!(std::cin>>x)||x< -10000||x>10000){std::cout<<"invalid\n";return 0;}input.push_back(x);}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 std::vector<int>selected;
 std::copy_if(input.begin(),input.end(),std::back_inserter(selected),[threshold](int x){return x>=threshold;});
 std::sort(selected.begin(),selected.end(),[](int a,int b){return a>b;});
 std::transform(selected.begin(),selected.end(),selected.begin(),[](int x){return 2*x;});
 long long sum=std::accumulate(selected.begin(),selected.end(),0LL);
 std::cout<<selected.size()<<' '<<sum<<'\n';
 for(std::size_t i=0;i<selected.size();++i){if(i)std::cout<<' ';std::cout<<selected[i];}
 std::cout<<'\n';
}
